import json

class Chatbot:
    def __init__(self):
        self.history = []

    def process_message(self, message):
        try:
            response = self.handle_message(message)
            self.history.append({'user': message, 'bot': response})
            return response
        except Exception as e:
            return f"Error processing message: {str(e)}"

    def handle_message(self, message):
        if message.lower() == "hello":
            return "Hello! How can I assist you today?"
        elif message.lower() == "bye":
            return "Goodbye! Have a great day!"
        else:
            return "I'm not sure how to respond to that."

# Example usage
chatbot = Chatbot()
print(chatbot.process_message("Hello"))  # Output: Hello! How can I assist you today?
print(chatbot.process_message("How are you?"))  # Output: I'm not sure how to respond to that.
print(chatbot.process_message("Bye"))  # Output: Goodbye! Have a great day!
