import json

class Chatbot:
    def __init__(self, filename='chat_history.json'):
        self.filename = filename
        self.history = self.load_history()

    def load_history(self):
        try:
            with open(self.filename, 'r') as file:
                return json.load(file)
        except FileNotFoundError:
            return []

    def save_history(self):
        with open(self.filename, 'w') as file:
            json.dump(self.history, file)

    def respond(self, user_input):
        response = "I'm sorry, I don't have a response for that."
        for interaction in reversed(self.history):
            if interaction['user_input'] == user_input:
                response = interaction['response']
                break
        self.history.append({'user_input': user_input, 'response': response})
        self.save_history()
        return response

# Example usage
chatbot = Chatbot()
print(chatbot.respond("Hello"))  # Initial interaction
print(chatbot.respond("Hello"))  # Previous interaction
